// Equivalent PDFs are generated by scripts/convert-form-templates.ps1.
const bundledPdfs: Record<string, string> = {
	'/forms/Prospectus-MAED-EM-KE.docx.docx': '/forms/Prospectus-MAED-EM-KE.pdf',
	'/forms/Prospectus-MAIT.docx': '/forms/Prospectus-MAIT.pdf',
	'/forms/Prospectus-MAM.docx': '/forms/Prospectus-MAM.pdf',
	'/forms/Prospectus-MSHM.docx': '/forms/Prospectus-MSHM.pdf'
};
export function bundledFormPdf(url: string): string | null { return bundledPdfs[url] ?? null; }
export function isPdfName(name: string): boolean { return /\.pdf$/i.test(name); }
